export interface ConnectorConfig {
  /** Airtable API key (Bearer token) */
  airtableApiKey: string
  /** Airtable Base ID */
  baseId: string
  /** Airtable Table ID or name */
  tableId: string
  /** Optional injected fetch for testing */
  fetch?: typeof fetch
}

export interface JotformSubmission {
  email: string
  first_name?: string
  last_name?: string
  phone?: string
  address?: string
  [key: string]: unknown
}

export interface AirtableRecord {
  id: string
  fields: Record<string, unknown>
}

export interface AirtableListResponse {
  records: AirtableRecord[]
  offset?: string
}

export interface AirtableUpdateResponse {
  id: string
  fields: Record<string, unknown>
}

export interface HandleResult {
  recordId: string
  updatedFields: string[]
}

function getFetch(config: ConnectorConfig): typeof fetch {
  return config.fetch ?? fetch
}

function buildFilterFormula(email: string): string {
  // Escape special characters in email for Airtable formula
  // According to docs: escape + as \+
  const escapedEmail = email.replace(/\+/g, '\\+').replace(/"/g, '\\"')
  return `{Email}="${escapedEmail}"`
}

function buildFindUrl(config: ConnectorConfig, formula: string): string {
  const encodedFormula = encodeURIComponent(formula)
  return `https://api.airtable.com/v0/${config.baseId}/${config.tableId}?filterByFormula=${encodedFormula}`
}

function buildUpdateUrl(config: ConnectorConfig, recordId: string): string {
  return `https://api.airtable.com/v0/${config.baseId}/${config.tableId}/${recordId}`
}

function isEmpty(value: unknown): boolean {
  return value === null || value === undefined || value === ''
}

async function findRecordByEmail(
  config: ConnectorConfig,
  email: string,
  fetchFn: typeof fetch
): Promise<AirtableRecord | null> {
  const formula = buildFilterFormula(email)
  const url = buildFindUrl(config, formula)

  const response = await fetchFn(url, {
    method: 'GET',
    headers: {
      Authorization: `Bearer ${config.airtableApiKey}`,
      'Content-Type': 'application/json',
    },
  })

  if (!response.ok) {
    throw new Error(`Airtable find record failed: ${response.status} ${response.statusText} at ${url}`)
  }

  const data = (await response.json()) as AirtableListResponse
  return data.records[0] ?? null
}

function buildPatchFields(
  submission: JotformSubmission,
  existingRecord: AirtableRecord
): Record<string, string> {
  const fieldMap: Array<{ source: keyof JotformSubmission; target: string }> = [
    { source: 'first_name', target: 'First Name' },
    { source: 'last_name', target: 'Last Name' },
    { source: 'phone', target: 'Phone' },
    { source: 'address', target: 'Address' },
  ]

  const patchFields: Record<string, string> = {}

  for (const { source, target } of fieldMap) {
    const sourceValue = submission[source]
    const existingValue = existingRecord.fields[target]

    // Only include if source has a value AND target is empty in Airtable
    if (!isEmpty(sourceValue) && isEmpty(existingValue)) {
      patchFields[target] = String(sourceValue)
    }
  }

  return patchFields
}

async function updateRecord(
  config: ConnectorConfig,
  recordId: string,
  fields: Record<string, string>,
  fetchFn: typeof fetch
): Promise<AirtableUpdateResponse> {
  const url = buildUpdateUrl(config, recordId)

  const response = await fetchFn(url, {
    method: 'PATCH',
    headers: {
      Authorization: `Bearer ${config.airtableApiKey}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ fields }),
  })

  if (!response.ok) {
    throw new Error(`Airtable update record failed: ${response.status} ${response.statusText} at ${url}`)
  }

  return (await response.json()) as AirtableUpdateResponse
}

export async function handle(
  payload: JotformSubmission,
  config: ConnectorConfig
): Promise<HandleResult> {
  // Validate required fields
  if (!payload.email || typeof payload.email !== 'string') {
    throw new Error('Missing required field: email')
  }

  const fetchFn = getFetch(config)

  // Find the Airtable record by email
  const record = await findRecordByEmail(config, payload.email, fetchFn)

  if (!record) {
    throw new Error(`No Airtable record found for email: ${payload.email}`)
  }

  // Build patch fields - only update empty fields
  const patchFields = buildPatchFields(payload, record)

  // If no fields to update, return early with empty updatedFields
  if (Object.keys(patchFields).length === 0) {
    return {
      recordId: record.id,
      updatedFields: [],
    }
  }

  // Perform the PATCH update
  await updateRecord(config, record.id, patchFields, fetchFn)

  return {
    recordId: record.id,
    updatedFields: Object.keys(patchFields),
  }
}

import { describe, it, expect, vi } from 'vitest'
import { handle, ConnectorConfig, JotformSubmission } from './connector'
import {
  SOURCE_EXAMPLE,
  TARGET_ENDPOINTS,
  contractFetch,
  fakeFetch,
  jsonResponse,
  RecordedCall,
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      airtableApiKey: 'test-api-key',
      baseId: 'appTestBase',
      tableId: 'tblTestTable',
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as JotformSubmission, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.recordId).toBe('recXXXXXXXXXXXX')
    // All fields in the example record are already populated, so no updates
    expect(result.updatedFields).toEqual([])
  })
})

describe('handle', () => {
  const baseConfig: ConnectorConfig = {
    airtableApiKey: 'test-api-key',
    baseId: 'appTestBase',
    tableId: 'tblTestTable',
  }

  it('throws when email is missing', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ error: 'not called' }, 500))
    const payload = { first_name: 'John' } as JotformSubmission
    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Missing required field: email')
    expect(calls.length).toBe(0)
  })

  it('throws when email is empty string', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ error: 'not called' }, 500))
    const payload = { email: '', first_name: 'John' } as JotformSubmission
    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Missing required field: email')
    expect(calls.length).toBe(0)
  })

  it('throws when no record found for email', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ records: [] }, 200))
    const payload = { email: 'notfound@example.com', first_name: 'John' } as JotformSubmission
    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('No Airtable record found for email')
    expect(calls.length).toBe(1)
    expect(calls[0].method).toBe('GET')
    expect(calls[0].url).toContain('filterByFormula')
  })

  it('finds record and updates empty fields only', async () => {
    // Airtable record has only First Name populated
    const existingRecord = {
      records: [
        {
          id: 'rec123',
          fields: {
            'First Name': 'John',
            'Last Name': '',
            Phone: null,
            Address: undefined,
          },
        },
      ],
    }

    const { fetch, calls } = fakeFetch((req) => {
      if (req.method === 'GET' && req.url.includes('filterByFormula')) {
        return jsonResponse(existingRecord, 200)
      }
      if (req.method === 'PATCH' && req.url.endsWith('/rec123')) {
        // Verify only empty fields are being updated
        const body = req.json as { fields: Record<string, string> }
        expect(body.fields).toEqual({
          'Last Name': 'Doe',
          Phone: '555-1234',
          Address: '123 Main St',
        })
        return jsonResponse({ id: 'rec123', fields: { ...existingRecord.records[0].fields, ...body.fields } }, 200)
      }
      return jsonResponse({ error: 'unexpected' }, 404)
    })

    const payload: JotformSubmission = {
      email: 'user@example.com',
      first_name: 'John',
      last_name: 'Doe',
      phone: '555-1234',
      address: '123 Main St',
    }

    const result = await handle(payload, { ...baseConfig, fetch })

    expect(calls.length).toBe(2)
    expect(calls[0].method).toBe('GET')
    expect(calls[1].method).toBe('PATCH')
    expect(result.recordId).toBe('rec123')
    expect(result.updatedFields).toEqual(['Last Name', 'Phone', 'Address'])
  })

  it('does not update non-empty fields in Airtable', async () => {
    // Airtable record already has all fields populated
    const existingRecord = {
      records: [
        {
          id: 'rec456',
          fields: {
            'First Name': 'Jane',
            'Last Name': 'Smith',
            Phone: '555-0000',
            Address: '456 Oak Ave',
          },
        },
      ],
    }

    const { fetch, calls } = fakeFetch((req) => {
      if (req.method === 'GET' && req.url.includes('filterByFormula')) {
        return jsonResponse(existingRecord, 200)
      }
      return jsonResponse({ error: 'should not PATCH' }, 404)
    })

    const payload: JotformSubmission = {
      email: 'user@example.com',
      first_name: 'John',
      last_name: 'Doe',
      phone: '555-1234',
      address: '123 Main St',
    }

    const result = await handle(payload, { ...baseConfig, fetch })

    expect(calls.length).toBe(1) // Only GET, no PATCH
    expect(calls[0].method).toBe('GET')
    expect(result.recordId).toBe('rec456')
    expect(result.updatedFields).toEqual([])
  })

  it('handles partial payload - only updates provided fields that are empty in Airtable', async () => {
    const existingRecord = {
      records: [
        {
          id: 'rec789',
          fields: {
            'First Name': '',
            'Last Name': 'Existing',
            Phone: '',
            Address: 'Existing Address',
          },
        },
      ],
    }

    const { fetch, calls } = fakeFetch((req) => {
      if (req.method === 'GET' && req.url.includes('filterByFormula')) {
        return jsonResponse(existingRecord, 200)
      }
      if (req.method === 'PATCH' && req.url.endsWith('/rec789')) {
        const body = req.json as { fields: Record<string, string> }
        // Only first_name and phone provided in payload, and both are empty in Airtable
        expect(body.fields).toEqual({
          'First Name': 'John',
          Phone: '555-1234',
        })
        return jsonResponse({ id: 'rec789', fields: { ...existingRecord.records[0].fields, ...body.fields } }, 200)
      }
      return jsonResponse({ error: 'unexpected' }, 404)
    })

    const payload: JotformSubmission = {
      email: 'user@example.com',
      first_name: 'John',
      phone: '555-1234',
      // last_name and address not provided
    }

    const result = await handle(payload, { ...baseConfig, fetch })

    expect(calls.length).toBe(2)
    expect(result.updatedFields).toEqual(['First Name', 'Phone'])
  })

  it('escapes plus sign in email for filterByFormula', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.method === 'GET' && req.url.includes('filterByFormula')) {
        // Verify the formula has escaped +
        expect(req.url).toContain('%5C%2B') // \+ encoded
        return jsonResponse({ records: [{ id: 'recPlus', fields: {} }] }, 200)
      }
      if (req.method === 'PATCH') {
        return jsonResponse({ id: 'recPlus', fields: {} }, 200)
      }
      return jsonResponse({ error: 'unexpected' }, 404)
    })

    const payload: JotformSubmission = {
      email: 'bob+1@gmail.com',
      first_name: 'Bob',
    }

    await handle(payload, { ...baseConfig, fetch })

    expect(calls.length).toBe(2)
  })

  it('throws on non-2xx response from Airtable find', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ error: 'Unauthorized' }, 401))
    const payload: JotformSubmission = { email: 'user@example.com' }

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow(
      'Airtable find record failed: 401 Unauthorized'
    )
    expect(calls.length).toBe(1)
  })

  it('throws on non-2xx response from Airtable update', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.method === 'GET') {
        return jsonResponse({ records: [{ id: 'recErr', fields: { 'First Name': '' } }] }, 200)
      }
      return jsonResponse({ error: 'Forbidden' }, 403)
    })

    const payload: JotformSubmission = {
      email: 'user@example.com',
      first_name: 'John',
    }

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow(
      'Airtable update record failed: 403 Forbidden'
    )
    expect(calls.length).toBe(2)
  })

  it('uses injected fetch from config', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.method === 'GET') {
        return jsonResponse({ records: [{ id: 'recInjected', fields: {} }] }, 200)
      }
      return jsonResponse({ id: 'recInjected', fields: {} }, 200)
    })

    const payload: JotformSubmission = { email: 'user@example.com', first_name: 'Test' }
    await handle(payload, { ...baseConfig, fetch })

    expect(calls.length).toBe(2)
  })
})

